import { createContext } from "svelte";
import type { HTMLAttributes } from "svelte/elements";
import type { NumberLocale } from "./number-field-machine.js";

export interface NumberFieldContext {
  readonly allowWheel: boolean;
  readonly ariaDescribedBy: HTMLAttributes<HTMLDivElement>["aria-describedby"];
  readonly ariaInvalid: HTMLAttributes<HTMLDivElement>["aria-invalid"];
  readonly ariaLabel: HTMLAttributes<HTMLDivElement>["aria-label"];
  readonly ariaLabelledBy: HTMLAttributes<HTMLDivElement>["aria-labelledby"];
  readonly ariaValue: number | null;
  readonly canDecrement: boolean;
  readonly canIncrement: boolean;
  readonly disabled: boolean;
  readonly displayValue: string;
  readonly defaultAccessibleName: string | undefined;
  readonly form: string | undefined;
  readonly id: string;
  readonly inputMode: "decimal" | "numeric";
  readonly locale: NumberLocale;
  readonly max: number | undefined;
  readonly min: number | undefined;
  readonly name: string | undefined;
  readonly readonly: boolean;
  readonly required: boolean;
  readonly size: "default" | "lg" | "sm";
  readonly scrubLabelId: string | undefined;
  commit(): void;
  registerInput(input: HTMLInputElement | null): void;
  registerScrubLabelId(id: string): () => void;
  scrub(delta: number): void;
  setEditing(editing: boolean): void;
  setInput(raw: string): void;
  stepBy(multiplier: number): void;
}

export const [getNumberFieldContext, setNumberFieldContext] = createContext<NumberFieldContext>();

export interface NumberLocale {
  decimal: string;
  digits: Map<string, string>;
  group: string;
  locale: string | string[] | undefined;
  minus: string;
  percent: string;
}

export function createNumberLocale(locale?: string | string[]): NumberLocale {
  const parts = new Intl.NumberFormat(locale).formatToParts(-12345.6);
  const digits = new Map<string, string>();
  const digitFormatter = new Intl.NumberFormat(locale, { useGrouping: false });
  for (let digit = 0; digit <= 9; digit += 1)
    digits.set(digitFormatter.format(digit), String(digit));
  return {
    decimal: parts.find((part) => part.type === "decimal")?.value ?? ".",
    digits,
    group: parts.find((part) => part.type === "group")?.value ?? ",",
    locale,
    minus: parts.find((part) => part.type === "minusSign")?.value ?? "-",
    percent:
      new Intl.NumberFormat(locale, { style: "percent" })
        .formatToParts(1)
        .find((part) => part.type === "percentSign")?.value ?? "%",
  };
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

export function parseNumber(raw: string, locale: NumberLocale): number | null {
  let normalized = raw.trim();
  if (!normalized || normalized === "-" || normalized === locale.minus) return null;
  for (const [localized, ascii] of locale.digits)
    normalized = normalized.split(localized).join(ascii);
  normalized = normalized
    .replace(new RegExp(escapeRegExp(locale.group), "g"), "")
    .replace(new RegExp(escapeRegExp(locale.decimal), "g"), ".")
    .replace(new RegExp(escapeRegExp(locale.minus), "g"), "-")
    .replace(/[\u00a0\u202f\s]/g, "")
    .replace(/[^0-9.+-]/g, "");
  if (!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(normalized)) return null;
  const value = Number(normalized);
  return Number.isFinite(value) ? value : null;
}

function decimalPlaces(value: number): number {
  const source = String(value).toLowerCase();
  if (source.includes("e-")) return Number(source.split("e-")[1] ?? 0);
  return source.split(".")[1]?.length ?? 0;
}

export function roundToStep(value: number, step = 1): number {
  const precision = Math.min(15, Math.max(decimalPlaces(value), decimalPlaces(step)));
  return Number(value.toFixed(precision));
}

export function clampValue(value: number, min?: number, max?: number, step = 1): number {
  return roundToStep(
    Math.min(max ?? Number.POSITIVE_INFINITY, Math.max(min ?? Number.NEGATIVE_INFINITY, value)),
    step,
  );
}

export function formatNumber(
  value: number | null,
  locale?: string | string[],
  options?: Intl.NumberFormatOptions,
): string {
  if (value == null || !Number.isFinite(value)) return "";
  return new Intl.NumberFormat(locale, options).format(value);
}

export type { CursorGrowIconProps } from "./cursor-grow-icon.svelte";
export { default as CursorGrowIcon } from "./cursor-grow-icon.svelte";
export type { NumberFieldDecrementProps } from "./number-field-decrement.svelte";
export {
  default as Decrement,
  default as NumberFieldDecrement,
} from "./number-field-decrement.svelte";
export type { NumberFieldGroupProps } from "./number-field-group.svelte";
export { default as Group, default as NumberFieldGroup } from "./number-field-group.svelte";
export type { NumberFieldIncrementProps } from "./number-field-increment.svelte";
export {
  default as Increment,
  default as NumberFieldIncrement,
} from "./number-field-increment.svelte";
export type { NumberFieldInputProps } from "./number-field-input.svelte";
export { default as Input, default as NumberFieldInput } from "./number-field-input.svelte";
export {
  clampValue,
  createNumberLocale,
  formatNumber,
  parseNumber,
} from "./number-field-machine.js";
export type { NumberFieldRootProps, NumberFieldSize } from "./number-field-root.svelte";
export { default as NumberField, default as Root } from "./number-field-root.svelte";
export type { NumberFieldScrubAreaProps } from "./number-field-scrub-area.svelte";
export {
  default as NumberFieldScrubArea,
  default as ScrubArea,
} from "./number-field-scrub-area.svelte";
